// Typed client for the backend. Requests go to /api/*, which Next.js rewrites to the backend
// (see next.config.ts), so the browser never needs the backend's address.

export type Item = {
  id: number;
  name: string;
  description: string | null;
  created_at: string;
  updated_at: string;
};

export type ItemPage = { items: Item[]; total: number };

export class ApiError extends Error {
  constructor(
    public status: number,
    message: string,
  ) {
    super(message);
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`/api${path}`, {
    ...init,
    headers: { "content-type": "application/json", ...init?.headers },
  });
  if (!response.ok) {
    const body = await response.json().catch(() => null);
    const detail = typeof body?.detail === "string" ? body.detail : response.statusText;
    throw new ApiError(response.status, detail);
  }
  return (response.status === 204 ? undefined : await response.json()) as T;
}

export const api = {
  health: () => request<{ status: string; database: string }>("/health"),
  listItems: () => request<ItemPage>("/items"),
  createItem: (data: { name: string; description?: string }) =>
    request<Item>("/items", { method: "POST", body: JSON.stringify(data) }),
  deleteItem: (id: number) => request<void>(`/items/${id}`, { method: "DELETE" }),
};

"use client";

import { useCallback, useEffect, useState } from "react";
import { api, type Item } from "@/lib/api";

export function ItemsPanel() {
  const [items, setItems] = useState<Item[]>([]);
  const [health, setHealth] = useState<"checking" | "ok" | "down">("checking");
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    try {
      await api.health();
      setHealth("ok");
      setItems((await api.listItems()).items);
    } catch {
      setHealth("down");
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  async function onCreate(event: React.FormEvent) {
    event.preventDefault();
    setBusy(true);
    setError(null);
    try {
      await api.createItem({ name, description: description || undefined });
      setName("");
      setDescription("");
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Something went wrong");
    } finally {
      setBusy(false);
    }
  }

  async function onDelete(id: number) {
    await api.deleteItem(id);
    await load();
  }

  return (
    <div className="grid gap-5 md:grid-cols-[1fr_1.4fr]">
      <section className="card flex flex-col gap-4">
        <div className="flex items-center justify-between">
          <h2 className="text-heading-sm font-semibold">New item</h2>
          <span
            className={`badge ${health === "ok" ? "bg-ink-soft text-surface-alt" : "border border-hairline text-mid-gray"}`}
          >
            API {health}
          </span>
        </div>
        <form onSubmit={onCreate} className="flex flex-col gap-2">
          <input
            className="input"
            placeholder="Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
          />
          <input
            className="input"
            placeholder="Description (optional)"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />
          {error && <p className="text-caption text-ember">{error}</p>}
          <div className="flex gap-2 pt-2">
            <button type="submit" className="btn-primary" disabled={busy || !name}>
              Create
            </button>
            <button type="button" className="btn-secondary" onClick={load}>
              Refresh
            </button>
          </div>
        </form>
      </section>

      <section className="card flex flex-col gap-3">
        <div className="flex items-baseline justify-between">
          <h2 className="text-heading-sm font-semibold">Items</h2>
          <span className="text-caption uppercase text-mid-gray">{items.length} total</span>
        </div>
        {items.length === 0 ? (
          <p className="text-mid-gray">No items yet.</p>
        ) : (
          <ul className="flex flex-col divide-y divide-hairline">
            {items.map((item) => (
              <li key={item.id} className="flex items-center justify-between gap-4 py-3">
                <div className="min-w-0">
                  <p className="font-medium">{item.name}</p>
                  {item.description && (
                    <p className="truncate text-mid-gray">{item.description}</p>
                  )}
                </div>
                <button
                  className="btn-outline text-ember"
                  onClick={() => onDelete(item.id)}
                  aria-label={`Delete ${item.name}`}
                >
                  Delete
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

import { ItemsPanel } from "@/components/items-panel";

export default function Home() {
  return (
    <main className="mx-auto flex max-w-[1280px] flex-col gap-12 px-6 py-16">
      <header className="flex flex-col gap-3">
        <span className="text-caption uppercase text-mid-gray">Next.js · FastAPI · PostgreSQL</span>
        <h1 className="text-display font-semibold">Monorepo starter</h1>
        <p className="max-w-xl text-body-lg text-mid-gray">
          The frontend talks to the backend through <code className="font-mono">/api</code>; the
          backend persists items in PostgreSQL through its service and repository layers.
        </p>
      </header>
      <ItemsPanel />
    </main>
  );
}

import type { NextConfig } from "next";

// Where the Next.js server forwards /api/* requests. In Docker this is the backend service;
// it is read at build time, so the frontend image is built with BACKEND_URL as a build arg.
const backendUrl = process.env.BACKEND_URL ?? "http://localhost:8000";

const nextConfig: NextConfig = {
  output: "standalone",
  cacheComponents: true,
  partialPrefetching: true,
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
  async rewrites() {
    return [{ source: "/api/:path*", destination: `${backendUrl}/api/:path*` }];
  },
};

export default nextConfig;

